package com.andye.warmod.radar.station;import com.andye.warmod.WarMod;import com.mojang.serialization.Codec;import java.util.*;import net.minecraft.resources.Identifier;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.datafix.DataFixTypes;import net.minecraft.world.level.saveddata.*;public final class RadarStationSavedData extends SavedData {private static final Codec<RadarStationSavedData> CODEC=RadarStationRecord.CODEC.listOf().xmap(RadarStationSavedData::new,d->List.copyOf(d.records.values()));public static final SavedDataType<RadarStationSavedData> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"radar_stations"),RadarStationSavedData::new,CODEC,DataFixTypes.SAVED_DATA_COMMAND_STORAGE);private final Map<UUID,RadarStationRecord>records=new LinkedHashMap<>();public RadarStationSavedData(){}private RadarStationSavedData(List<RadarStationRecord>loaded){for(var r:loaded)records.put(r.radarId(),r);}public static RadarStationSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(TYPE);}public Collection<RadarStationRecord>records(){return List.copyOf(records.values());}public int size(){return records.size();}public void put(RadarStationRecord r){records.put(r.radarId(),r);setDirty();}public void remove(UUID id){if(records.remove(id)!=null)setDirty();}}